def mark_users_with_unused_invites(apps, schema_editor):
    """People who were sent an invite and never used it are, by definition, still onboarding."""
    User = apps.get_model('accounts', 'User')
    PasswordResetToken = apps.get_model('accounts', 'PasswordResetToken')
    pending_ids = PasswordResetToken.objects.filter(purpose='invite', is_used=False).values_list('user_id', flat=True)
    User.objects.filter(pk__in=list(pending_ids), is_active=True, must_change_password=True).update(activation_pending=True)


